async function streamPdf(res, opts) {
  const PDFDocument = (await import("pdfkit")).default;
  const doc = new PDFDocument({
    size: "LETTER",
    margins: { top: 60, bottom: 60, left: 60, right: 60 },
    bufferPages: true,
    info: { Title: opts.title, Producer: "SCCC IT Hub" }
  });
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader(
    "Content-Disposition",
    `attachment; filename="${opts.filename}"`
  );
  doc.pipe(res);
  doc.font("Helvetica-Bold").fontSize(20).fillColor("#0f172a").text(opts.title, { align: "left" });
  if (opts.subtitle) {
    doc.moveDown(0.2);
    doc.font("Helvetica").fontSize(11).fillColor("#475569").text(opts.subtitle);
  }
  doc.moveDown(0.5);
  doc.moveTo(doc.page.margins.left, doc.y).lineTo(doc.page.width - doc.page.margins.right, doc.y).strokeColor("#cbd5e1").lineWidth(0.75).stroke();
  doc.moveDown(0.6);
  for (const s of opts.sections) {
    switch (s.kind) {
      case "heading": {
        const sizes = { 1: 16, 2: 13, 3: 12 };
        doc.moveDown(0.4);
        doc.font("Helvetica-Bold").fontSize(sizes[s.level]).fillColor("#0f172a").text(s.text);
        doc.moveDown(0.2);
        break;
      }
      case "paragraph": {
        const font = s.bold && s.italic ? "Helvetica-BoldOblique" : s.bold ? "Helvetica-Bold" : s.italic ? "Helvetica-Oblique" : "Helvetica";
        doc.font(font).fontSize(11).fillColor("#1f2937").text(s.text || " ", { align: "left" });
        doc.moveDown(0.3);
        break;
      }
      case "kv": {
        doc.font("Helvetica-Bold").fontSize(10).fillColor("#475569").text(`${s.label}: `, { continued: true });
        doc.font("Helvetica").fontSize(10).fillColor("#0f172a").text(s.value || "\u2014");
        break;
      }
      case "bullet": {
        doc.font("Helvetica").fontSize(11).fillColor("#1f2937").text(`\u2022  ${s.text}`, {
          indent: 12
        });
        break;
      }
      case "spacer":
        doc.moveDown(0.6);
        break;
    }
  }
  const range2 = doc.bufferedPageRange();
  for (let i = 0; i < range2.count; i++) {
    doc.switchToPage(range2.start + i);
    const bottom = doc.page.height - 40;
    doc.font("Helvetica").fontSize(8).fillColor("#94a3b8").text(
      `${opts.title}  \xB7  Page ${i + 1} of ${range2.count}  \xB7  Generated ${(/* @__PURE__ */ new Date()).toLocaleString()}`,
      doc.page.margins.left,
      bottom,
      { align: "center", width: doc.page.width - doc.page.margins.left - doc.page.margins.right }
    );
  }
  doc.end();
}

