async function buildDocxBuffer(title, blocks) {
  const { Document: Document2, Packer: Packer2, Paragraph: Paragraph2, HeadingLevel: HeadingLevel2 } = await Promise.resolve().then(() => (init_dist(), dist_exports));
  const headingMap = {
    1: HeadingLevel2.HEADING_1,
    2: HeadingLevel2.HEADING_2,
    3: HeadingLevel2.HEADING_3
  };
  const children = [
    new Paragraph2({ text: title, heading: HeadingLevel2.HEADING_1 }),
    new Paragraph2({ text: "" })
  ];
  for (const b of blocks) {
    if (b.heading) {
      children.push(
        new Paragraph2({
          text: b.heading,
          heading: headingMap[b.level ?? 2]
        })
      );
    }
    if (b.text) {
      for (const line2 of b.text.split(/\n+/)) {
        children.push(new Paragraph2({ text: line2 }));
      }
    }
    if (b.bullets) {
      for (const item of b.bullets) {
        children.push(new Paragraph2({ text: item, bullet: { level: 0 } }));
      }
    }
    children.push(new Paragraph2({ text: "" }));
  }
  const doc = new Document2({ sections: [{ children }] });
  return Packer2.toBuffer(doc);
}
function sendDocx(res, buffer2, filename) {
  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.wordprocessingml.document");
  res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
  return res.send(buffer2);
}
